contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function performing the test; take an address parameter to range over inputs
    function run(address caller) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // perform the state-changing call as a top-level statement
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read balances after the call
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: for any input caller, either the call reverted or c's balance is zero and this contract's balance did not decrease
        assert(reverted || (afterC == 0 && afterThis >= beforeThis));
    }

    receive() external payable { }
}

